// Forge's service worker — hand-written rather than generated by a build
// plugin. The app's build is a two-phase Vite → Nitro pipeline (see
// vite.config.ts's comment), and every workbox-based generator we tried
// wrote its output to whichever directory each phase happened to be using
// at that exact moment, so its `sw.js` never reliably ended up where Nitro
// actually serves static files from. A plain static file avoids that
// entirely — it's copied to the output the same way favicon.ico already is.
//
// Scope, deliberately: this does NOT try to precache the app's hashed JS/CSS
// bundle. That would mean keeping a manifest of exact build output filenames
// in sync by hand (the thing build plugins exist to automate), which isn't
// worth it for what this buys — everything the app needs is already fully
// functional offline via localStorage once a page has loaded once normally.
// What this SW does cache is the two things repeat/offline use actually
// benefits from: the OCR assets (so re-scanning doesn't re-fetch ~9MB) and
// the app shell's own HTML (so reopening the installed app with a flaky or
// absent connection still opens instead of showing a browser error).

const CACHE_VERSION = "v1";
const OCR_CACHE = `forge-ocr-${CACHE_VERSION}`;
const PAGES_CACHE = `forge-pages-${CACHE_VERSION}`;
const CURRENT_CACHES = [OCR_CACHE, PAGES_CACHE];

self.addEventListener("install", () => {
  self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(
          keys.filter((key) => !CURRENT_CACHES.includes(key)).map((key) => caches.delete(key)),
        ),
      )
      .then(() => self.clients.claim()),
  );
});

self.addEventListener("fetch", (event) => {
  const { request } = event;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  // OCR assets: cache-first — they're versioned by path, not by content hash,
  // so once cached they're reused as-is until CACHE_VERSION changes above.
  if (url.pathname.startsWith("/tesseract/")) {
    event.respondWith(
      caches.open(OCR_CACHE).then(async (cache) => {
        const cached = await cache.match(request);
        if (cached) return cached;
        const response = await fetch(request);
        if (response.ok) cache.put(request, response.clone());
        return response;
      }),
    );
    return;
  }

  // App shell navigations: network-first, falling back to the last cached
  // response for that URL when the network is unavailable.
  if (request.mode === "navigate") {
    event.respondWith(
      fetch(request)
        .then((response) => {
          caches.open(PAGES_CACHE).then((cache) => cache.put(request, response.clone()));
          return response;
        })
        .catch(() => caches.match(request)),
    );
  }
});

// Rest-timer notifications sent by the send-rest-notifications edge function
// (see supabase/functions/) while the page itself may be fully suspended —
// this is what lets a rest-complete alert land with the screen locked.
self.addEventListener("push", (event) => {
  let payload = { title: "Rest complete", body: "Time to lift — back to Forge." };
  try {
    if (event.data) payload = { ...payload, ...event.data.json() };
  } catch {
    /* fall back to the default copy above */
  }
  event.waitUntil(
    self.registration.showNotification(payload.title, {
      body: payload.body,
      tag: "forge-rest",
      icon: "/pwa/icon-192.png",
    }),
  );
});

self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  event.waitUntil(
    self.clients.matchAll({ type: "window", includeUncontrolled: true }).then((clients) => {
      const existing = clients.find((c) => "focus" in c);
      if (existing) return existing.focus();
      return self.clients.openWindow("/session");
    }),
  );
});
